function cycleInfo(d=new Date()){const o=((diff(d,parseDate(state.settings.anchorDate))%21)+21)%21;return{day:o+1,index:o,marker:CYCLE[o],phase:o<=5?"Six-Day Work Block":o<=7?"Two-Day Break":o<=16?"Nine-Day Work Block":"Four-Day Break"}}
function isVacation(d=new Date()){const k=dateKey(d);return k>=state.settings.vacationStart&&k<=state.settings.vacationEnd}
function autoMode(d=new Date()){if(isVacation(d))return"Vacation";const c=cycleInfo(d);if(c.marker==="W")return"Workday";const p=new Date(d),n=new Date(d);p.setDate(p.getDate()-1);n.setDate(n.getDate()+1);if(cycleInfo(p).marker==="W")return"Recovery Day";if(cycleInfo(n).marker==="W")return"Open Day";return"Growth Day"}
