function rollover(){const t=dateKey(),w=weekKeyFor();if(state.weekKey!==w){if(state.weekKey)archiveCurrentWeek(state.weekKey);state.weekKey=w;state.progress={Cybersecurity:0,Training:0,Creative:0,Learning:0};state.progressNotes=""}if(state.dayKey!==t){state.dayKey=t;state.energy="Standard";state.mission="Evolution";state.nextAction="";state.modeOverride="";state.dailyNotes="";state.dailyTasks=freshTasks(autoMode());state.wellbeing.draft={};state.training.equipment=rhythmPlan().equipment}if(!state.dailyTasks.length)state.dailyTasks=freshTasks(currentMode());state.version="0.3.5-beta";state.mission="Evolution";save()}
