function libraryFor(group,preferred){const list=[...(exerciseLibrary[group.region]||[preferred])];if(preferred&&!list.includes(preferred))list.unshift(preferred);return list}
function exerciseKey(i){return `${new Date().getDay()}-${i}`}
function defaultExerciseDraft(group,i,factor){const preferred=exerciseFor(group),count=Math.max(1,Math.round(group.sets*factor));return{name:preferred,setCount:count,sets:Array.from({length:count},()=>({load:"",reps:"",rpe:""})),notes:""}}
function ensureExerciseDraft(group,i,factor){const k=exerciseKey(i);state.training.draft[k]??=defaultExerciseDraft(group,i,factor);const d=state.training.draft[k];d.sets??=[];d.setCount=Math.max(1,Number(d.setCount||d.sets.length||1));while(d.sets.length<d.setCount)d.sets.push({load:"",reps:"",rpe:""});d.sets=d.sets.slice(0,d.setCount);return d}
function activeTrainingSession(){const w=selectedWorkout(),today=dateKey();if(!state.training.activeSession||state.training.activeSession.dayKey!==today)state.training.activeSession={id:`session-${Date.now()}`,dayKey:today,weekKey:state.weekKey,title:w.title,exerciseIds:[],startedAt:new Date().toISOString()};return state.training.activeSession}
function weeklyTrainingStats(){const exercises=(state.training.exerciseHistory||[]).filter(x=>x.weekKey===state.weekKey),sessions=(state.training.history||[]).filter(x=>x.weekKey===state.weekKey);return{sessions:sessions.length,exercises:exercises.length,sets:exercises.reduce((s,x)=>s+Number(x.workingSets||0),0),reps:exercises.reduce((s,x)=>s+Number(x.totalReps||0),0),volume:exercises.reduce((s,x)=>s+Number(x.volume||0),0),muscles:new Set(exercises.map(x=>x.region)).size}}
function recalcTrainingSession(session){const exercises=(session.exerciseIds||[]).map(id=>(state.training.exerciseHistory||[]).find(x=>x.id===id)).filter(Boolean);session.exerciseIds=exercises.map(x=>x.id);session.exerciseCount=exercises.length;session.workingSets=exercises.reduce((s,x)=>s+Number(x.workingSets||0),0);session.totalReps=exercises.reduce((s,x)=>s+Number(x.totalReps||0),0);session.volume=exercises.reduce((s,x)=>s+Number(x.volume||0),0);return session}
function deleteExerciseRecord(recordId){const record=(state.training.exerciseHistory||[]).find(x=>x.id===recordId);if(!record||!confirm(`Delete ${record.name} from training history?`))return;state.training.exerciseHistory=state.training.exerciseHistory.filter(x=>x.id!==recordId);if(state.training.activeSession)state.training.activeSession.exerciseIds=(state.training.activeSession.exerciseIds||[]).filter(x=>x.id!==recordId);state.training.history.forEach(session=>{session.exerciseIds=(session.exerciseIds||[]).filter(id=>id!==recordId);recalcTrainingSession(session)});if(state.training.editingId===recordId)state.training.editingId=null;save();renderWorkout();renderProgress("progressList");renderProgress("progressListFull");renderGoalEngine();renderHQ()}
function deleteTrainingSession(sessionId){const session=(state.training.history||[]).find(x=>x.id===sessionId);if(!session||!confirm(`Delete this ${session.title} session and its linked exercises?`))return;const linked=new Set(session.exerciseIds||[]);state.training.history=state.training.history.filter(x=>x.id!==sessionId);state.training.exerciseHistory=(state.training.exerciseHistory||[]).filter(x=>!linked.has(x.id));save();renderWorkout();renderProgress("progressList");renderProgress("progressListFull");renderGoalEngine();renderHQ()}
function loadExerciseForEditing(recordId){const record=(state.training.exerciseHistory||[]).find(x=>x.id===recordId);if(!record)return;const groups=selectedWorkout().groups,i=groups.findIndex(g=>g.region===record.region);if(i<0)return alert(`${record.region} is not part of today's programmed workout. Editing unmatched historical muscle groups will be expanded later.`);state.training.draft[exerciseKey(i)]={name:record.name,setCount:Math.max(1,(record.sets||[]).length),sets:(record.sets||[]).map(x=>({load:x.load,reps:x.reps,rpe:x.rpe})),notes:record.notes||""};state.training.editingId=recordId;save();renderWorkout();show("today");savedMessage(id("workoutResult"),`<strong>Editing ${esc(record.name)}.</strong><br><span class="muted">Adjust the ${esc(record.region)} card and press Save Exercise.</span>`)}

const workouts={0:{title:"Recovery + Mobility",tag:"Recovery",groups:[g("Hips & spine","Hip flexors, glutes, spinal stabilizers","Mobility flow","Bodyweight",2,10,false,true),g("Core","Transverse abdominis, obliques","Dead bug","Bodyweight",3,10,false,true)]},1:{title:"Upper Body Strength",tag:"Strength",groups:[g("Chest","Pectoralis major","Bench press","Anterior deltoids, triceps",3,8),g("Back","Latissimus dorsi","Pull-ups","Rhomboids, teres major, biceps, brachialis",3,8,false,true),g("Shoulders","Anterior and lateral deltoids","Dumbbell shoulder press","Triceps, upper chest",3,8),g("Biceps","Biceps brachii","Dumbbell curl","Long/short head emphasis; brachialis secondary",3,8),g("Triceps","Triceps brachii","Close-grip push-up","Chest, anterior deltoids",3,8,false,true),g("Core","Rectus abdominis, obliques","Plank","Spinal and shoulder stabilizers",3,30,false,true)]},2:{title:"Boxing + Conditioning",tag:"Combat",groups:[g("Shoulder endurance","Deltoids, serratus anterior","Heavy-bag rounds","Triceps, core",6,3,true,true),g("Core rotation","Obliques, transverse abdominis","Shadowboxing with pivots","Hips, shoulders",4,3,true,true)]},3:{title:"Lower Body Strength",tag:"Strength",groups:[g("Quadriceps","Vastus group, rectus femoris","Goblet squat","Glutes, adductors, core",4,8),g("Posterior chain","Hamstrings, gluteus maximus","Dumbbell Romanian deadlift","Erector spinae, grip",4,8),g("Glutes","Gluteus maximus and medius","Bulgarian split squat","Quadriceps, adductors",3,8),g("Calves","Gastrocnemius, soleus","Single-leg calf raise","Foot stabilizers",3,12,false,true),g("Core","Obliques, transverse abdominis","Suitcase hold","Grip, spinal stabilizers",3,30)]},4:{title:"Upper Pull + Arms",tag:"Strength",groups:[g("Back","Latissimus dorsi, rhomboids","Pull-ups or one-arm dumbbell row","Biceps, rear delts",4,8),g("Rear shoulders","Posterior deltoids","Bent-over reverse fly","Rhomboids, traps",3,10),g("Biceps","Biceps brachii","Preacher curl or concentration curl","Short-head emphasis; brachialis",3,8),g("Forearms","Brachioradialis, wrist flexors","Hammer curl","Brachialis, biceps",3,10),g("Core","Rectus abdominis","Hanging knee raise","Hip flexors, grip",3,10,false,true)]},5:{title:"Athletic Conditioning",tag:"Conditioning",groups:[g("Full body","Legs, shoulders, core","Dumbbell thruster","Chest, triceps",4,10),g("Chest endurance","Pectorals","Push-up intervals","Triceps, delts",4,12,false,true),g("Posterior chain","Glutes, hamstrings","Dumbbell swing","Core, grip",4,15)]},6:{title:"Combat Integration",tag:"Mixed",groups:[g("Boxing output","Shoulders, triceps, core","Heavy-bag rounds or shadowboxing","Hips, calves",6,3,true,true),g("Chest","Pectorals, front delts, triceps","Push-up","Core stabilizers",4,10,false,true),g("Back","Lats, rhomboids, rear delts","One-arm dumbbell row","Biceps, grip",4,10),g("Legs","Quadriceps, glutes","Goblet squat","Adductors, core",4,10),g("Neck & trunk","Neck flexors/extensors, core","Isometric neck + plank","Shoulder stabilizers",3,20,false,true)]}};
function selectedWorkout(){if(state.training.useGoalPlan&&state.training.goalPlan?.groups?.length)return{title:`${state.training.goalPlan.name} Goal Session`,tag:"Goal",groups:state.training.goalPlan.groups};return workouts[new Date().getDay()]}
function createGoalGroup(item){const primary={Back:"Latissimus dorsi, rhomboids and traps","Rear shoulders":"Posterior deltoids and upper back","Posterior chain":"Hamstrings, glutes and spinal erectors",Shoulders:"Deltoids",Chest:"Pectoralis major",Biceps:"Biceps brachii",Triceps:"Triceps brachii",Forearms:"Brachialis and forearms","Full body":"Full-body strength and conditioning","Shoulder endurance":"Deltoids and conditioning",Core:"Trunk stabilizers","Core rotation":"Obliques and rotational chain","Boxing output":"Striking output and conditioning",Legs:"Quadriceps and glutes","Neck & trunk":"Neck and trunk stabilizers"}[item.region]||item.region;return g(item.region,primary,item.exercise,item.why,item.sets,item.reps,/round/i.test(item.exercise),/push-up|pull-up|plank|shadowboxing|mobility|hanging|calf raise|neck/i.test(item.exercise))}
function generateGoalPlan(){const key=id("physiqueGoalSelect").value,def=goalDefinitions[key],items=def[state.training.equipment]||def.home;state.training.goal=key;state.training.goalPlan={key,name:def.name,description:def.description,muscles:def.muscles,targets:def.targets,items:clone(items),groups:items.map(createGoalGroup),createdAt:new Date().toISOString()};state.training.useGoalPlan=false;save();renderGoalEngine();renderWorkout()}
function weeklyGoalStats(){const def=goalDefinitions[state.training.goal]||goalDefinitions["oni-back"],week=(state.training.exerciseHistory||[]).filter(x=>x.weekKey===state.weekKey),by={};week.forEach(x=>by[x.region]=(by[x.region]||0)+Number(x.workingSets||0));return{def,by}}
function guideFor(name){return exerciseGuides[name]||{pattern:"generic",steps:[`Set up the ${name} with stable posture and controlled range.`,`Move through the exercise without rushing or using unnecessary momentum.`,`Stop the set when technique noticeably breaks down.`],mistake:"Use a manageable load and prioritize a repeatable range of motion."}}
