function archiveCurrentWeek(key){ensureVlaData();if(!key||state.weeklyArchives.some(x=>x.weekKey===key))return;const studies=(state.cyber.history||[]).filter(x=>x.weekKey===key),work=(state.work.history||[]).filter(x=>x.weekKey===key),training=(state.training.history||[]).filter(x=>x.weekKey===key),checkins=(state.wellbeing.history||[]).filter(x=>x.weekKey===key);state.weeklyArchives.unshift({weekKey:key,archivedAt:new Date().toISOString(),progress:clone(state.progress),studyMinutes:studies.reduce((a,x)=>a+Number(x.minutes||0),0),studyDays:new Set(studies.filter(x=>Number(x.minutes)>0).map(x=>x.dayKey)).size,zeroDays:studies.filter(x=>Number(x.minutes)===0).length,workHours:work.reduce((a,x)=>a+Number(x.hours||0),0),offDayOtHours:work.filter(x=>x.type==="Off-day OT").reduce((a,x)=>a+Number(x.hours||0),0),trainingSessions:training.length,checkins:checkins.length,notes:state.progressNotes||""});save()}
function currentWeekMetrics(){ensureVlaData();const studies=(state.cyber.history||[]).filter(x=>x.weekKey===state.weekKey),work=(state.work.history||[]).filter(x=>x.weekKey===state.weekKey),training=(state.training.history||[]).filter(x=>x.weekKey===state.weekKey);return{studyMinutes:studies.reduce((a,x)=>a+Number(x.minutes||0),0),studyDays:new Set(studies.filter(x=>Number(x.minutes)>0).map(x=>x.dayKey)).size,zeroDays:studies.filter(x=>Number(x.minutes)===0).length,workHours:work.reduce((a,x)=>a+Number(x.hours||0),0),offDayOtHours:work.filter(x=>x.type==="Off-day OT").reduce((a,x)=>a+Number(x.hours||0),0),trainingSessions:training.length}}
function assessmentHtml(){const cur=currentWeekMetrics(),prev=state.weeklyArchives[0];if(!prev)return`<div class="simple-item"><strong>Insufficient historical data</strong><div class="muted">This week is being recorded as the baseline. A week-over-week verdict will appear after the first Monday–Sunday archive.</div></div>`;const studyDelta=cur.studyMinutes-prev.studyMinutes,trainingDelta=cur.trainingSessions-prev.trainingSessions;let verdict="Maintaining",reason=[];if(studyDelta>30){verdict="Improving";reason.push(`Cybersecurity study increased by ${studyDelta} minutes.`)}else if(studyDelta<-30){verdict=cur.offDayOtHours>0?"Workload-constrained":"Declining";reason.push(`Cybersecurity study decreased by ${Math.abs(studyDelta)} minutes.`)}else reason.push("Cybersecurity effort is near last week's level.");if(trainingDelta>0)reason.push(`Training increased by ${trainingDelta} session${trainingDelta===1?"":"s"}.`);if(trainingDelta<0)reason.push(`Training decreased by ${Math.abs(trainingDelta)} session${trainingDelta===-1?"":"s"}.`);if(cur.offDayOtHours)reason.push(`${cur.offDayOtHours} off-day OT hours affected available capacity.`);return`<div class="simple-item ${verdict==="Improving"?"assessment-good":"assessment-warn"}"><strong>Overall trajectory: ${verdict}</strong><div class="muted">${reason.join(" ")}</div></div>`}
function renderObjectives(){const list=id("objectiveList");if(!list)return;const objs=state.cyber.objectives||[];list.innerHTML=objs.length?objs.map(o=>`<div class="simple-item objective-row"><div><strong>${esc(o.code)} · ${esc(o.title)}</strong>${o.active?` <span class="tag">ACTIVE</span>`:""}<div class="muted">${esc(o.chapter||"No chapter")} · ${esc(o.status||"Not Started")} · ${Number(o.studyMinutes||0)} min logged</div><div><strong>Goal:</strong> ${esc(o.goal||"No mastery goal entered.")}</div>${o.notes?`<div class="muted">${esc(o.notes)}</div>`:""}</div><div class="objective-actions"><button data-active-objective="${o.id}">Set active</button><button data-cycle-objective="${o.id}">Advance status</button><button data-edit-objective="${o.id}">Edit</button><button data-delete-objective="${o.id}">Delete</button></div></div>`).join(""):'<div class="simple-item muted">No learning objectives added yet.</div>';list.querySelectorAll("[data-active-objective]").forEach(b=>b.onclick=()=>{state.cyber.objectives.forEach(o=>o.active=o.id===b.dataset.activeObjective);const o=state.cyber.objectives.find(o=>o.active);if(o){state.cyber.objective=`${o.code} ${o.title}`.trim();state.cyber.chapter=o.chapter||state.cyber.chapter}save();renderCyber();renderObjectives()});list.querySelectorAll("[data-cycle-objective]").forEach(b=>b.onclick=()=>{const o=state.cyber.objectives.find(x=>x.id===b.dataset.cycleObjective),statuses=["Not Started","Studying","Reviewing","Mastered"];o.status=statuses[(statuses.indexOf(o.status)+1)%statuses.length];save();renderObjectives()});list.querySelectorAll("[data-edit-objective]").forEach(b=>b.onclick=()=>{const o=state.cyber.objectives.find(x=>x.id===b.dataset.editObjective);const title=prompt("Objective title",o.title);if(title===null)return;const goal=prompt("Mastery goal",o.goal);if(goal===null)return;o.title=title.trim();o.goal=goal.trim();save();renderObjectives();renderCyber()});list.querySelectorAll("[data-delete-objective]").forEach(b=>b.onclick=()=>{if(confirm("Delete this learning objective?")){state.cyber.objectives=state.cyber.objectives.filter(x=>x.id!==b.dataset.deleteObjective);save();renderObjectives();renderCyber()}})}
function estimatedFinance(){const m=currentWeekMetrics(),base=Number(state.finance.baseRate||0),mult=Number(state.finance.otMultiplier||1.5),regular=Math.min(40,m.workHours),ot=Math.max(0,m.workHours-40),gross=regular*base+ot*base*mult,net=gross*(1-Number(state.finance.deductionRate||0)/100);return{...m,regular,ot,gross,net}}
function renderOperations(){ensureVlaData();if(!id("priorityTimeline"))return;id("priorityTimeline").innerHTML=[["Primary mission","Evolution"],["Current era",state.strategy.currentEra],["Primary vehicle",state.strategy.primaryVehicle],["Supporting income",state.strategy.supportingVehicle],["Long-term build",state.strategy.longTerm]].map(([a,b])=>`<div class="summary-item"><span>${esc(a)}</span><strong>${esc(b)}</strong></div>`).join("");const work=state.work.history||[];id("workHistory").innerHTML=work.length?work.slice(0,12).map(x=>`<div class="simple-item data-row"><strong>${esc(x.type)} · ${x.hours} hours</strong><div class="muted">${esc(x.date)}${x.affected?` · Affected: ${esc(x.affected)}`:""}</div>${x.notes?`<div>${esc(x.notes)}</div>`:""}</div>`).join(""):'<div class="simple-item muted">No work context logged.</div>';const f=estimatedFinance(),goal=Number(state.finance.weeklyIncomeGoal||0),remaining=Math.max(0,goal-f.net),extraRate=Number(state.finance.baseRate||0)*Number(state.finance.otMultiplier||1.5)*(1-Number(state.finance.deductionRate||0)/100),hoursNeeded=extraRate?remaining/extraRate:0;id("financeSummary").innerHTML=[["Hours this week",f.workHours],["Regular / OT",`${f.regular} / ${f.ot}`],["Estimated gross",`$${f.gross.toFixed(2)}`],["Estimated net",`$${f.net.toFixed(2)}`],["Off-day OT",`${f.offDayOtHours} hr`],["Extra hours to net goal",goal?hoursNeeded.toFixed(1):"Set a goal"]].map(([a,b])=>`<div class="summary-item"><span>${a}</span><strong>${b}</strong></div>`).join("");id("obligationList").innerHTML=state.finance.obligations.length?state.finance.obligations.map(x=>`<div class="simple-item"><strong>${esc(x.name)} · ${esc(x.type)}</strong><div class="muted">$${Number(x.amount||0).toFixed(2)}${x.due?` · Due ${esc(x.due)}`:""}</div></div>`).join(""):'<div class="simple-item muted">No debts, loans, bills, or expenses entered.</div>';id("acquisitionList").innerHTML=state.acquisitions.length?state.acquisitions.map(x=>`<div class="simple-item"><strong>${esc(x.name)} · ${esc(x.priority)}</strong><div class="muted">$${Number(x.cost||0).toFixed(2)} · Supports ${esc(x.supports||"general evolution")}</div></div>`).join(""):'<div class="simple-item muted">No acquisitions entered.</div>';id("assetList").innerHTML=state.assets.length?state.assets.map(x=>`<div class="simple-item"><strong>${esc(x.name)} · ${esc(x.condition)}</strong><div class="muted">${esc(x.need||"No current need")} · $${Number(x.cost||0).toFixed(2)}</div></div>`).join(""):'<div class="simple-item muted">No assets entered.</div>'}
function renderVlaEnhancements(){ensureVlaData();if(id("missionInput")){id("missionInput").value="Evolution";id("missionInput").readOnly=true}renderObjectives();renderOperations();const targets=[id("progressListFull"),id("progressList")].filter(Boolean);targets.forEach((el,i)=>{const old=el.querySelector?.(".vla-assessment");if(old)old.remove();const box=document.createElement("div");box.className="vla-assessment";box.innerHTML=`<div class="section-head history-head"><h3>HUD assessment</h3><span class="tag">ANALYZED</span></div>${assessmentHtml()}`;el.appendChild(box)})}
ensureVlaData();
if(id("addObjectiveBtn"))id("addObjectiveBtn").onclick=()=>{const code=id("objectiveCodeInput").value.trim(),title=id("objectiveTitleInput").value.trim(),goal=id("objectiveGoalInput").value.trim();if(!code&&!title)return alert("Enter an objective number or title.");state.cyber.objectives.push({id:`obj-${Date.now()}`,code,title,goal,status:id("objectiveStatusInput").value,chapter:id("objectiveChapterInput").value.trim(),notes:id("objectiveNotesInput").value.trim(),active:state.cyber.objectives.length===0,studyMinutes:0});["objectiveCodeInput","objectiveTitleInput","objectiveGoalInput","objectiveChapterInput","objectiveNotesInput"].forEach(x=>id(x).value="");save();renderObjectives();renderCyber()};
if(id("logWorkBtn"))id("logWorkBtn").onclick=()=>{const hours=Number(id("workHoursInput").value||0);state.work.history.unshift({id:`work-${Date.now()}`,dayKey:dateKey(parseDate(id("workDateInput").value||dateKey())),weekKey:weekKeyFor(parseDate(id("workDateInput").value||dateKey())),date:id("workDateInput").value||dateKey(),type:id("workTypeInput").value,hours,affected:id("workAffectedInput").value.trim(),notes:id("workNotesInput").value.trim()});save();renderOperations();renderVlaEnhancements()};
if(id("saveFinanceConfigBtn"))id("saveFinanceConfigBtn").onclick=()=>{state.finance.baseRate=Number(id("baseRateInput").value||0);state.finance.otMultiplier=Number(id("otMultiplierInput").value||1.5);state.finance.deductionRate=Number(id("deductionRateInput").value||0);state.finance.weeklyIncomeGoal=Number(id("weeklyIncomeGoalInput").value||0);save();renderOperations()};
if(id("addObligationBtn"))id("addObligationBtn").onclick=()=>{const name=id("obligationNameInput").value.trim();if(!name)return;state.finance.obligations.push({id:`obl-${Date.now()}`,name,type:id("obligationTypeInput").value,amount:Number(id("obligationBalanceInput").value||0),due:id("obligationDueInput").value});save();renderOperations()};
if(id("addAcquisitionBtn"))id("addAcquisitionBtn").onclick=()=>{const name=id("acquisitionNameInput").value.trim();if(!name)return;state.acquisitions.push({id:`acq-${Date.now()}`,name,cost:Number(id("acquisitionCostInput").value||0),priority:id("acquisitionPriorityInput").value,supports:id("acquisitionSupportsInput").value.trim(),status:"Planned"});save();renderOperations()};
if(id("addAssetBtn"))id("addAssetBtn").onclick=()=>{const name=id("assetNameInput").value.trim();if(!name)return;state.assets.push({id:`asset-${Date.now()}`,name,condition:id("assetConditionInput").value,need:id("assetNeedInput").value.trim(),cost:Number(id("assetCostInput").value||0)});save();renderOperations()};
const oldRender=render;render=function(){oldRender();renderVlaEnhancements();if(id("baseRateInput")){id("baseRateInput").value=state.finance.baseRate||"";id("otMultiplierInput").value=state.finance.otMultiplier||1.5;id("deductionRateInput").value=state.finance.deductionRate||"";id("weeklyIncomeGoalInput").value=state.finance.weeklyIncomeGoal||"";id("workDateInput").value=dateKey()}};
if("serviceWorker"in navigator)navigator.serviceWorker.register("service-worker.js");render();
